import {
  IPHONE_FIXTURE_EMPTY_TEXT,
  IPHONE_FIXTURE_HTTP_NULL,
  IPHONE_FIXTURE_HTTP_POST,
  IPHONE_FIXTURE_ROUTE_PREFIX,
  IPHONE_FIXTURE_ROUTE_RECT,
  IPHONE_FIXTURE_ROUTE_SCREENSHOT,
  IPHONE_FIXTURE_ROUTE_SESSION,
  IPHONE_FIXTURE_ROUTE_SOURCE,
  IPHONE_FIXTURE_ROUTE_STATUS,
  IPHONE_FIXTURE_ROUTES,
} from "./constants"

export function iphoneFixtureResponse(path: string, method: string): string {
  const route = path.replace(IPHONE_FIXTURE_ROUTE_PREFIX, IPHONE_FIXTURE_EMPTY_TEXT)
  switch (route) {
    case IPHONE_FIXTURE_ROUTE_STATUS:
    case IPHONE_FIXTURE_ROUTE_SOURCE:
    case IPHONE_FIXTURE_ROUTE_RECT:
    case IPHONE_FIXTURE_ROUTE_SCREENSHOT:
      return IPHONE_FIXTURE_ROUTES[route]
    case IPHONE_FIXTURE_ROUTE_SESSION:
      if (method === IPHONE_FIXTURE_HTTP_POST) {
        return IPHONE_FIXTURE_ROUTES[route]
      }
      return IPHONE_FIXTURE_HTTP_NULL
    default:
      return IPHONE_FIXTURE_HTTP_NULL
  }
}
